const workspaceBar=document.createElement('section');workspaceBar.className='workspacebar';workspaceBar.innerHTML='<div class="workflowtabs"><button data-workspace="build" class="active">◈ בנייה</button><button data-workspace="wire">⌁ חיווט</button><button data-workspace="code">{ } קוד</button><button data-workspace="measure">∿ מדידה</button><button data-workspace="learn">▤ למידה</button></div><div class="historycontrols"><button id="undoaction" title="ביטול פעולה · Ctrl+Z">ביטול</button><button id="redoaction" title="ביצוע חוזר · Ctrl+Y">שחזור</button><button id="duplicatepart">שכפול רכיב</button><button id="circuitcheck">בדיקת חיווט</button><button id="projectexports">ייצוא</button></div>';document.querySelector('.projectbar').after(workspaceBar);document.body.dataset.workspace='build';
function workspaceMode(mode){document.body.dataset.workspace=mode;$('lessons').classList.toggle('active',mode==='learn');$('labnav').classList.toggle('active',mode!=='learn');document.querySelectorAll('[data-workspace]').forEach(b=>b.classList.toggle('active',b.dataset.workspace===mode));if(mode==='wire')setTool('wire');else setTool('select');if(mode==='code'){mobilePanel('workspace');openCode(true)}if(mode==='measure'){mobilePanel('workspace');scope.scrollIntoView({behavior:'smooth',block:'center'})}if(mode==='learn'){mobilePanel('workspace');renderCourse();document.querySelector('main').scrollIntoView({behavior:'smooth',block:'start'})}}document.querySelectorAll('[data-workspace]').forEach(b=>b.onclick=()=>workspaceMode(b.dataset.workspace));$('lessons').onclick=()=>workspaceMode('learn');$('labnav').onclick=()=>workspaceMode('build');
const anglebar=document.createElement('div');anglebar.className='anglebar';anglebar.innerHTML='<span>מבט</span><button data-camera="iso" class="active">פרספקטיבה</button><button data-camera="top">עליון</button><button data-camera="front">קדמי</button><button data-camera="right">צד</button><label><input type="checkbox" id="gridtoggle" checked> רשת</label><button id="fitview">התאמה למסך</button>';$('canvas').parentElement.append(anglebar);document.querySelectorAll('[data-camera]').forEach(b=>b.onclick=()=>{const key=b.dataset.camera;angle=key==='right'?Math.PI/2:key==='iso'?-.55:0;tilt=key==='top'?0.01:key==='iso'?.72:1.5;window.visualRevision++;document.querySelectorAll('[data-camera]').forEach(e=>e.classList.toggle('active',e===b))});$('gridtoggle').onchange=e=>{window.showGrid=e.target.checked;window.visualRevision++};$('fitview').onclick=()=>{zoom=Math.max(.4,Math.min(1.3,7/Math.max(7,...nodes.map(n=>Math.abs(n.x)*2+2),...nodes.map(n=>Math.abs(n.z)*2+2))));angle=-.55;tilt=.72;window.visualRevision++};
let undoStates=[],undoIndex=-1,historyRestoring=false,historyDebounce;function currentProject(){return{version:3,nodes:structuredClone(nodes),wires:structuredClone(wires),idseq,title:$('projecttitle').textContent}}function rememberAction(){if(historyRestoring)return;const state=JSON.stringify(currentProject());if(undoStates[undoIndex]===state)return;undoStates=undoStates.slice(0,undoIndex+1);undoStates.push(state);if(undoStates.length>30)undoStates.shift();undoIndex=undoStates.length-1;historyControls()}function historyControls(){$('undoaction').disabled=undoIndex<=0;$('redoaction').disabled=undoIndex>=undoStates.length-1}function restoreAction(delta){clearTimeout(historyDebounce);rememberAction();if(undoIndex+delta<0||undoIndex+delta>=undoStates.length)return;historyRestoring=true;stopCode();undoIndex+=delta;const data=JSON.parse(undoStates[undoIndex]);nodes=data.nodes;wires=data.wires;idseq=data.idseq;activeBoard=nodes.find(n=>catalog.find(c=>c.type===n.type).board)?.id;selected=nodes.find(n=>n.id===selected)?.id??nodes[0]?.id;program=null;pinState={};$('projecttitle').textContent=data.title;renderDetail();update();if(!$('codepanel').hidden)openCode(false);historyRestoring=false;historyControls();toast(delta<0?'הפעולה בוטלה':'הפעולה שוחזרה')}$('undoaction').onclick=()=>restoreAction(-1);$('redoaction').onclick=()=>restoreAction(1);const projectUpdate=update;update=function(){projectUpdate();if(!historyRestoring){clearTimeout(historyDebounce);historyDebounce=setTimeout(rememberAction,220)}renderBenchChecks()};document.addEventListener('pointerup',()=>{if(drag?.node)setTimeout(rememberAction,0)});document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select,[contenteditable]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();restoreAction(e.shiftKey?1:-1)}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();restoreAction(1)}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();$('save').click()}});$('duplicatepart').onclick=()=>{const n=nodes.find(n=>n.id===selected);if(!n)return toast('בחרו רכיב לשכפול');rememberAction();const clone=structuredClone(n);clone.id=++idseq;clone.x=Math.min(5,clone.x+.7);clone.z=Math.min(4,clone.z+.6);nodes.push(clone);select(clone.id);update();rememberAction()};
const titleInput=document.createElement('input');titleInput.id='projectname';titleInput.setAttribute('aria-label','שם הפרויקט');titleInput.maxLength=80;titleInput.value=$('projecttitle').textContent;titleInput.placeholder='שם הפרויקט';const rename=document.createElement('button');rename.id='renameproject';rename.title='שינוי שם הפרויקט';rename.textContent='עריכת שם';document.querySelector('.projectbar>div').append(rename);rename.onclick=()=>{showModal('<h1>שם הפרויקט</h1><label class="projectnamelabel">בחרו שם שיעזור לכם למצוא את הניסוי<input id="newprojectname" maxlength="80"></label><button id="applyprojectname" class="run">שמירת השם</button>');$('newprojectname').value=$('projecttitle').textContent;$('applyprojectname').onclick=()=>{const name=$('newprojectname').value.trim();if(!name)return;rememberAction();$('projecttitle').textContent=name;rememberAction();$('modal').close()}};
function wiringDiagnostics(){const messages=[];const used=new Map();for(const w of wires){if(w.length!==2||w.some(p=>!nodes.find(n=>n.id===p.id)))messages.push({level:'error',text:'חיבור מתייחס לרכיב שאינו במשטח.'});for(const p of w){const k=p.id+':'+p.pin;used.set(k,(used.get(k)||0)+1)}}for(const n of nodes){const c=catalog.find(c=>c.type===n.type);if(c.pins.length&&c.pins.every((p,i)=>!used.has(n.id+':'+i)))messages.push({level:'note',text:c.name+' אינו מחובר למעגל.'});if(c.python)messages.push({level:'note',text:c.name+': Python זמין לעריכה וייצוא; אין הרצת מעבד.'});if(c.sensor&&!c.input)messages.push({level:'note',text:c.name+': רכיב להרכבה ולמידה, ללא סימולציה פעילה.'})}const result=simulate();messages.unshift({level:result.current>0?'ok':result.msg?.includes('קצר')||result.msg?.includes('הפוך')?'error':'note',text:result.msg||'לא קיים מעגל להרצה.'});if(result.current>.02&&result.active?.some(id=>nodes.find(n=>n.id===id)?.type==='led'))messages.unshift({level:'error',text:'זרם ה־LED גבוה מ־20mA. הגדילו את הנגד הטורי.'});return messages}
function renderBenchChecks(){if(!$('checksummary'))return;const now=performance.now();if(now-(renderBenchChecks.last||0)<400)return;renderBenchChecks.last=now;const messages=wiringDiagnostics(),errors=messages.filter(m=>m.level==='error').length;$('checksummary').textContent=errors?errors+' אזהרות בחיווט':'בדיקות המעגל';$('checklistmini').innerHTML=messages.slice(0,3).map(m=>`<p class="${m.level}">${escapeHtml(m.text)}</p>`).join('')}
const checks=document.createElement('section');checks.className='benchchecks';checks.innerHTML='<div><b id="checksummary">בדיקות המעגל</b><button id="detailchecks">פרטים</button></div><div id="checklistmini"></div>';document.querySelector('.instruments').before(checks);$('circuitcheck').onclick=$('detailchecks').onclick=()=>{const rows=wiringDiagnostics();showModal('<span class="eyebrow">CIRCUIT REVIEW</span><h1>בדיקת החיבורים</h1><p>הבדיקה משתמשת במודל המעגל הזמין במעבדה. זו אינה בדיקת התאמה לחומרה פיזית.</p><div class="diagnostics">'+rows.map(r=>`<p class="${r.level}">${r.level==='ok'?'✓':r.level==='error'?'!':'·'} ${escapeHtml(r.text)}</p>`).join('')+'</div>')};
function projectBOM(){const rows=new Map();for(const n of nodes){const c=catalog.find(c=>c.type===n.type),key=c.type+':'+n.value+':'+(n.package||'');if(!rows.has(key))rows.set(key,{name:c.name,model:c.en,value:n.value,unit:c.unit,package:n.package||'Through-hole / module',quantity:0});rows.get(key).quantity++}return[...rows.values()]}
function wiringRows(){return wires.map((w,i)=>{const ends=w.map(p=>{const n=nodes.find(n=>n.id===p.id),c=n&&catalog.find(c=>c.type===n.type);return c?c.name+' #'+n.id+' / '+c.pins[p.pin]:'הדק חסר'});return{id:i+1,from:ends[0],to:ends[1]}})}function csvCell(s){return'"'+String(s).replaceAll('"','""')+'"'}$('projectexports').onclick=()=>{const bom=projectBOM(),connections=wiringRows();showModal('<span class="eyebrow">PROJECT PACKAGE</span><h1>מהמשטח לפרויקט מסודר</h1><div class="exportbuttons"><button id="bomcsv">רשימת רכיבים CSV</button><button id="wirecsv">רשימת חיבורים CSV</button><button id="wholejson">פרויקט JSON עם קוד</button><button id="schematicsvg">סכמה SVG</button></div><h3>רשימת רכיבים</h3><table><thead><tr><th>רכיב</th><th>ערך</th><th>כמות</th></tr></thead><tbody>'+bom.map(r=>`<tr><td>${r.name}</td><td>${r.value} ${r.unit}</td><td>${r.quantity}</td></tr>`).join('')+'</tbody></table><p>הייצוא כולל את החיבורים והרכיבים הקיימים במשטח. מיקומי ההדקים הם לוגיים; יש לאמת pinout של הדגם הפיזי לפני הבנייה.</p>');$('bomcsv').onclick=()=>download('voltlab-bom.csv','\uFEFF'+[['name','model','value','unit','package','quantity'],...bom.map(r=>Object.values(r))].map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv;charset=utf-8');$('wirecsv').onclick=()=>download('voltlab-wiring.csv','\uFEFF'+[['wire','from','to'],...connections.map(r=>Object.values(r))].map(r=>r.map(csvCell).join(',')).join('\n'),'text/csv;charset=utf-8');$('wholejson').onclick=()=>download('voltlab-project.json',JSON.stringify(currentProject(),null,2));$('schematicsvg').onclick=exportSchematic};
function exportSchematic(){const xml=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');const pos=n=>({x:500+n.x*70,y:350+n.z*60});let svg='<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="700" viewBox="0 0 1000 700"><rect width="1000" height="700" fill="#f4f7fb"/><text x="970" y="35" text-anchor="end" font-size="20" font-family="Arial">'+xml($('projecttitle').textContent)+'</text>';for(const w of wires){const ends=w.map(p=>{const n=nodes.find(n=>n.id===p.id);if(!n)return{x:0,y:0};const c=catalog.find(c=>c.type===n.type),center=pos(n),count=c.pins.length;return{x:center.x+(p.pin<count/2?-50:50),y:center.y+(p.pin%Math.ceil(count/2)-Math.floor(count/4))*10}});svg+=`<path d="M${ends[0].x} ${ends[0].y} H${(ends[0].x+ends[1].x)/2} V${ends[1].y} H${ends[1].x}" fill="none" stroke="#277e79" stroke-width="2"/>`}for(const n of nodes){const c=catalog.find(c=>c.type===n.type),p=pos(n);svg+=`<rect x="${p.x-50}" y="${p.y-25}" width="100" height="50" rx="6" fill="#e5edf6" stroke="#26384d"/><text x="${p.x}" y="${p.y-32}" text-anchor="middle" font-family="Arial" font-size="12">${xml(c.name)} #${n.id}</text><text x="${p.x}" y="${p.y+5}" text-anchor="middle" font-family="Arial" font-size="11">${n.value} ${xml(c.unit)}</text>`;c.pins.forEach((pin,i)=>{const count=c.pins.length,x=p.x+(i<count/2?-50:50),y=p.y+(i%Math.ceil(count/2)-Math.floor(count/4))*10;svg+=`<circle cx="${x}" cy="${y}" r="3" fill="#19776d"/><text x="${x+(i<count/2?-5:5)}" y="${y-3}" text-anchor="${i<count/2?'end':'start'}" font-family="Arial" font-size="8">${xml(pin)}</text>`})}svg+='<text x="25" y="675" font-family="Arial" font-size="11" fill="#5b687a">VoltLab — logical connection diagram / verify physical pinout</text></svg>';download('voltlab-schematic.svg',svg,'image/svg+xml')}
