$('save').onclick=()=>{try{rememberAction();const projects=JSON.parse(localStorage.getItem('voltlab-projects')||'[]');projects.unshift({...currentProject(),date:new Date().toLocaleString('he-IL')});localStorage.setItem('voltlab-projects',JSON.stringify(projects.slice(0,10)));toast('הפרויקט, השם והקוד נשמרו בדפדפן הזה')}catch{toast('לא ניתן לשמור את הפרויקט בדפדפן הזה')}};const namedProjectList=$('projects').onclick;$('projects').onclick=()=>{namedProjectList();let list=[];try{list=JSON.parse(localStorage.getItem('voltlab-projects')||'[]')}catch{}$('modalbody').querySelectorAll('.modalcard h3').forEach((h,i)=>{if(list[i]?.title)h.textContent=list[i].title})};const namedLoadProject=loadProject;loadProject=function(i){namedLoadProject(i);try{const p=JSON.parse(localStorage.getItem('voltlab-projects')||'[]')[i];if(typeof p?.title==='string')$('projecttitle').textContent=p.title.slice(0,80)}catch{}rememberAction()};
const oldCapabilities=$('capabilities').onclick;$('capabilities').onclick=()=>{oldCapabilities();const div=document.createElement('div');div.innerHTML='<h3>מה נוסף בסביבת העבודה?</h3><p>מסלול למידה עם משימות, מפרש תנאים וחישובים, היסטוריית 30 פעולות, שכפול רכיבים, מבטי מצלמה, בדיקת חיווט וייצוא BOM, חיבורים וסכמה.</p><h3>הרחבות שעדיין אינן ממומשות</h3><p>אמולציית CPU מלאה, קומפילציית Arduino ו־ESP-IDF, פרוטוקולי I²C/SPI/OneWire, סימולציית Python/Java, מנוע רובוטיקה ופיזיקה, עריכת גופים וייצוא STL של מכלולים, סנכרון ענן ואלפי מודלים חשמליים מאומתים.</p>';$('modalbody').append(div)};
